// План specs/invoices.md 1.1 / 1.2 (кейс .qa/tests/invoices/IN-01). Pre-Prod, preprod-ttp (TTP Test Locks), EN.
// Ничего не создаёт: позиции не добавляются, клиент не выбирается.
import { test, expect } from '../../fixtures';
import { ROLE, customerAlert, customerSearch, customerToast, invoiceNumber, openNewInvoiceForm, watchInvoiceWrites } from './invoice-helpers';

test.describe('Счета — New Invoice без клиента (#1a4863)', () => {
  for (const device of ['@desktop', '@android'] as const) {
    test(`Create Invoice without a customer: no invoice, "Select a customer to bill." at Bill To, customer search opened #1a4863 ${device}`, async ({ asUser }) => {
      const page = await asUser(ROLE);
      await openNewInvoiceForm(page);
      await expect(customerAlert(page)).toHaveCount(0);

      // Шаг 2: Create Invoice без клиента
      const writes = watchInvoiceWrites(page);
      await page.getByRole('button', { name: 'Create Invoice' }).click();

      // Сообщение: тост + красный текст у Bill To (источник: «מה רצוי» — הודעה ליד Bill To; коммент программиста — текст)
      await expect(customerAlert(page)).toBeVisible();
      await expect(customerAlert(page)).toHaveClass(/text-red/);
      const billTo = page.locator('div').filter({ has: page.getByText('Bill To:', { exact: true }) }).filter({ has: customerAlert(page) }).last();
      await expect(billTo, 'красный текст — в блоке Bill To').toBeVisible();
      await expect(customerToast(page)).toBeVisible();

      // Поиск клиента открыт и в фокусе, список виден (коммент программиста — открывается поиск клиентов)
      await expect(customerSearch(page)).toBeVisible();
      await expect(customerSearch(page)).toBeFocused();
      await expect(page.getByText('TTP Customer', { exact: true }).filter({ visible: true })).toBeVisible();

      // Счёт не создан (источник: «מה קיים»/«מה רצוי» — без клиента счёт не создаётся)
      await expect(page.getByRole('button', { name: 'Create Invoice' })).toBeVisible();
      expect(await invoiceNumber(page)).toBe('N/A');
      expect(writes, 'запросов создания счёта без клиента быть не должно').toEqual([]);
    });
  }
});
